--Funcoes de Agrupamento  --quantas pessoas trabalham no setor 19? select count(*) from funcionarios where setor_id = 19  --não funciona select count(*), func_nome from funcionarios where setor_id = 19  --contar quantos funcionarios do setor 19 possuem gerente select count(gerente_id) as comGerente,  	   count(*) geral  from funcionarios where setor_id = 19  --********************************************************* -- Função de somatória  --quanto é o total pago com salarios a todos os funcionarios --que trabalham no setor 5 e possuem o gerente 22? select sum(func_salario) as totalPago from funcionarios where setor_id = 5 and gerente_id = 22  select * from funcionarios where setor_id = 5 and gerente_id = 22  ----------------------------------------------- --qual o valor médio do salario dos  --funcionarios do setor_id = 7  select avg(func_salario) Media from funcionarios where setor_id = 7  -------------------------------------------------- --qual o maior e menor valor de salarios dos funcionarios --que os gerentes 11, 19 e 1 gerenciam  select min(func_salario) Menor, max(func_salario) Maior from funcionarios where gerente_id in (11, 19, 1)  --não funciona se eu quiser mostrar esse maior e menor --separado por gerente select gerente_id, min(func_salario) Menor,  	   max(func_salario) Maior from funcionarios where gerente_id in (11, 19, 1)